function ownRangeTrack(p, w = 210) {
  const h = 14, pad = 5;
  if (!p.band) {
    return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img"
        aria-label="no prior range: fewer than three previous games">
      <text x="0" y="11" font-family="${C("--mono")}" font-size="9" fill="${C("--ink-3")}">
        fewer than 3 prior games</text></svg>`;
  }
  const b = p.band;
  const lo = Math.min(b.lo, p.this_week), hi = Math.max(b.hi, p.this_week);
  const span = (hi - lo) || 1;
  const X = v => pad + ((v - lo) / span) * (w - pad * 2);
  const mid = h / 2, vx = X(p.this_week);
  const col = p.flag ? C("--out") : C("--obs");
  const mark = p.flag === "high"
    ? `<path d="M${vx} ${mid - 5.2} L${vx + 4.3} ${mid + 4.1} L${vx - 4.3} ${mid + 4.1}Z"
             fill="${col}" stroke="${C("--paper")}" stroke-width="1"/>`
    : p.flag === "low"
      ? `<path d="M${vx} ${mid + 5.2} L${vx - 4.3} ${mid - 4.1} L${vx + 4.3} ${mid - 4.1}Z"
             fill="${col}" stroke="${C("--paper")}" stroke-width="1"/>`
      : `<circle cx="${vx}" cy="${mid}" r="3.7" fill="${col}" stroke="${C("--paper")}" stroke-width="1"/>`;
  return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img"
      aria-label="${esc(p.name)}: ${p.this_week} snaps against his own prior range of ${b.lo} to ${b.hi}, median ${b.med}">
    <line x1="${X(b.lo)}" y1="${mid}" x2="${X(b.hi)}" y2="${mid}" stroke="${C("--rule")}"/>
    <line x1="${X(b.lo)}" y1="${mid - 3.4}" x2="${X(b.lo)}" y2="${mid + 3.4}" stroke="${C("--rule")}"/>
    <line x1="${X(b.hi)}" y1="${mid - 3.4}" x2="${X(b.hi)}" y2="${mid + 3.4}" stroke="${C("--rule")}"/>
    <rect x="${X(b.p25)}" y="${mid - 4.6}" width="${Math.max(1, X(b.p75) - X(b.p25))}" height="9.2"
          fill="${C("--ref")}" stroke="${C("--rule")}" stroke-width=".75"/>
    <line x1="${X(b.med)}" y1="${mid - 5.6}" x2="${X(b.med)}" y2="${mid + 5.6}"
          stroke="${C("--ink-2")}" stroke-width="1.2"/>
    ${mark}
  </svg>`;
}

function flowRows(list) {
  return list.map(p => `
    <tr class="${p.flag ? "flagged" : ""}">
      <td class="lbl">${esc(p.name)}</td>
      <td class="mid" style="font-size:9pt">${p.position}</td>
      <td class="grp">${p.group}</td>
      <td class="r ${p.flag ? "out" : ""}">${p.this_week}</td>
      <td class="trk" style="width:2.1in"><div class="track">${ownRangeTrack(p)}</div></td>
      <td class="r mid">${p.band ? p.band.med : "—"}</td>
      <td class="r mid">${p.total}</td>
    </tr>`).join("");
}
const SPLIT = 16;

